#[allow(unused_variables)] fn ability_0_affinity(q: &dyn Query, source: ObjectId, player: PlayerId, costed: Costed, targets: &[Target]) -> CostDelta { if costed != Costed::Spell(source) { return CostDelta::NONE; } let asker = &Asker::new(source, player); let count = q.permanents_of(player).into_iter().filter(|&id| (q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Assassin)) || q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Mercenary)) || q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Pirate)) || q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Rogue)) || q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Warlock)))).count(); CostDelta::less(count as u32) }

